package com.example.data.model

/**
 * Access Token Tier generated by Admin for Users.
 * L1: Best (Institutional/Pro Tier - unconstrained capital, full 34 bots, advanced ML/DL + high-speed order execution)
 * L2: Normal (Growth Portfolio - Level 1K to 10K, balanced risk controls, portfolio hedging)
 * L3: Affordable (Starter/Micro Tier - Level 0 to 1K, strict micro sizing, capital protection)
 */
enum class TokenTier(
    val code: String,
    val titleSwahili: String,
    val titleEn: String,
    val descriptionSwahili: String,
    val descriptionEn: String,
    val maxCapitalUsd: Double,
    val maxActiveBots: Int,
    val allowedMarketAccess: String
) {
    L1_BEST(
        code = "L1",
        titleSwahili = "L1 - Taasisi / Bora Zaidi (Best)",
        titleEn = "L1 - Institutional / Elite (Best)",
        descriptionSwahili = "Kiwango cha juu zaidi: Ufikiaji kamili wa boti zote 34, masoko yote 51, uwezo mkubwa wa mtaji, na uchanganuzi wa kiwango cha D.E. Shaw & Nobel Quant.",
        descriptionEn = "Highest tier: Full access to all 34 bots, all 51 active markets, unconstrained capital allocation, and complete D.E. Shaw & Nobel Quant core.",
        maxCapitalUsd = 100000.0,
        maxActiveBots = 34,
        allowedMarketAccess = "CRYPTO, FOREX, METALS, COMMODITIES, STOCKS, DERIV SYNTHETICS, ETFS"
    ),
    L2_NORMAL(
        code = "L2",
        titleSwahili = "L2 - Kawaida / Ukuaji (Normal)",
        titleEn = "L2 - Standard / Growth (Normal)",
        descriptionSwahili = "Kiwango cha kawaida: Ufikiaji wa boti 24 za ukuaji wa mtaji ($1K - $10K), ulinzi wa hedging, na uchanganuzi wa Order Flow & Volume Profile.",
        descriptionEn = "Standard tier: Access to 24 growth portfolio bots ($1K - $10K), portfolio hedging, order flow and volume profiling.",
        maxCapitalUsd = 10000.0,
        maxActiveBots = 24,
        allowedMarketAccess = "CRYPTO, FOREX, METALS, COMMODITIES, DERIV SYNTHETICS"
    ),
    L3_AFFORDABLE(
        code = "L3",
        titleSwahili = "L3 - Nafuu / Mtaji Mdogo (Affordable)",
        titleEn = "L3 - Affordable / Starter",
        descriptionSwahili = "Kiwango cha nafuu: Ufikiaji wa boti 18 za mtaji mdogo ($0 - $1K), ulinzi mkali wa pips 15, na ada ndogo za biashara.",
        descriptionEn = "Affordable tier: Access to 18 starter & micro bots ($0 - $1K), strict 15-pip loss prevention, micro 0.01 lot sizing.",
        maxCapitalUsd = 1000.0,
        maxActiveBots = 18,
        allowedMarketAccess = "CRYPTO MICRO, FOREX CENT, DERIV SYNTHETICS MICRO"
    )
}

enum class UserRole {
    USER,
    ADMIN
}

data class AuthUser(
    val id: String,
    val email: String,
    val fullName: String,
    val role: UserRole,
    val activeToken: String? = null,
    val tokenTier: TokenTier? = null,
    val tokenExpiryTimestamp: Long? = null,
    val registeredAt: Long = System.currentTimeMillis(),
    val emailNotificationEnabled: Boolean = true
)

data class GeneratedSystemToken(
    val tokenString: String,
    val tier: TokenTier,
    val createdByAdminId: String,
    val createdAt: Long = System.currentTimeMillis(),
    val expiresAt: Long = System.currentTimeMillis() + (30L * 24 * 60 * 60 * 1000), // 30 days
    val isRedeemed: Boolean = false,
    val redeemedByEmail: String? = null,
    val redeemedAt: Long? = null
)

data class EmailNotificationRecord(
    val id: String = java.util.UUID.randomUUID().toString(),
    val recipientEmail: String,
    val subject: String,
    val body: String,
    val sentTimestamp: Long = System.currentTimeMillis(),
    val notificationType: String, // "TOKEN_ACTIVATED", "TRADE_EXECUTION", "RISK_ALERT", "ADMIN_DISPATCH"
    val status: String = "DELIVERED"
)

enum class ChatSender {
    USER,
    ADMIN,
    GENERAL_MOTHER_BRAIN,
    MASTER_ASSISTANT
}

data class ChatMessage(
    val id: String = java.util.UUID.randomUUID().toString(),
    val sender: ChatSender,
    val senderName: String,
    val text: String,
    val timestamp: Long = System.currentTimeMillis(),
    val isDirectiveToGeneral: Boolean = false,
    val isMasterAdvice: Boolean = false
)
